<?php $cols=(int)$room['columns_count'];$aisle=(int)$room['aisle_after']; ?>
<section class="university-room-sheet" aria-label="Seating plan for <?= e($room['code']) ?>">
  <header><div>Seating Plan (<?= e($room['school_label']) ?>)</div><div>Room No - <?= e($room['code']) ?></div><div><?= e($document['allocation']['session_label']) ?></div></header>
  <table class="university-seat-grid" aria-label="Physical seat positions"><colgroup><?php for($c=1;$c<=$cols;$c++):?><col><?php if($c===$aisle):?><col class="invigilator-aisle"><?php endif;?><?php endfor;?></colgroup><tbody>
    <?php for($r=1;$r<=(int)$room['rows_count'];$r++):?><tr><?php for($c=1;$c<=$cols;$c++):$entry=$room['grid'][$r][$c]??null;$student=$entry['student']??null;?><td class="<?= !empty($entry['seat']['is_blocked'])?'blocked-position':'' ?>" title="<?= e(($entry['seat']['seat_label']??'').' '.($student['programme_code']??'')) ?>"><?= $student?e($student['roll_no_original']):'&nbsp;' ?></td><?php if($c===$aisle):?><td class="invigilator-aisle"></td><?php endif;?><?php endfor;?></tr><?php endfor;?>
    <tr class="desk-label-row"><?php foreach([[1,$aisle],[$aisle+1,$cols]] as $side=>$bounds):[$start,$end]=$bounds;$desk=1;for($c=$start;$c<=$end;$c+=2):?><td colspan="<?= min(2,$end-$c+1) ?>">DESK-<?= $desk++ ?></td><?php endfor;if($side===0):?><td class="invigilator-aisle"></td><?php endif;endforeach;?></tr>
    <tr class="white-board-row"><td colspan="<?= $cols+1 ?>">WHITE BOARD</td></tr>
    <tr class="invigilator-label-row"><td colspan="<?= $aisle ?>">Left Side of Invigilator</td><td class="invigilator-aisle"><svg viewBox="0 0 58 36" aria-label="Invigilator" role="img"><ellipse cx="29" cy="18" rx="26" ry="16" fill="#f79646" stroke="#000" stroke-width="2.5"/><ellipse cx="20" cy="14" rx="2.8" ry="2"/><ellipse cx="38" cy="14" rx="2.8" ry="2"/><path d="M16 23 Q29 32 42 23" fill="none" stroke="#000" stroke-width="2.5"/></svg></td><?php if($cols>$aisle):?><td colspan="<?= $cols-$aisle ?>">Right Side of Invigilator</td><?php endif;?></tr>
  </tbody></table>
  <table class="university-student-summary"><thead><tr><th>S.No.</th><th>Student Detail</th><th>No. of Student</th></tr></thead><tbody><?php foreach($room['summary'] as $i=>$item):?><tr><td><?= $i+1 ?></td><td><?= e($item['detail']) ?></td><td><?= (int)$item['count'] ?></td></tr><?php endforeach;for($i=count($room['summary']);$i<3;$i++):?><tr><td><?= $i+1 ?></td><td></td><td></td></tr><?php endfor;?><tr class="room-total"><td></td><td>Total</td><td><?= (int)$room['assigned_count'] ?></td></tr></tbody></table>
</section>
